import { Toaster } from "@/shared/ui/toaster";
import { Toaster as Sonner } from "@/shared/ui/sonner";
import { TooltipProvider } from "@/shared/ui/tooltip";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { ThemeProvider } from "@/shared/ui/ThemeProvider";
import { AuthProvider } from "@/hooks/useAuth";
import { PermissionsProvider } from "@/shared/hooks/usePermissions";
import { StoreProvider } from "@/shared/contexts/StoreContext";

import { ProtectedRoute } from "@/shared/ui/ProtectedRoute";
import { PermissionProtectedRoute } from "@/shared/ui/PermissionProtectedRoute";
import { DashboardLayout } from "@/features/dashboard/ui/DashboardLayout";
import { RootRedirect } from "@/shared/ui/RootRedirect";
import Index from "./pages/Index";
import Dashboard from "./features/dashboard/ui/Dashboard.page";
// Removido: páginas de painel (Câmara Fria, Estoque Insumos, Embalagens)
import Produtos from "./features/produtos/ui/Produtos.page";
import ProductAnalytics from "./features/produtos/ui/ProductAnalytics.page";

import LabelPrinting from "./pages/LabelPrinting";
import BatchTraceability from "./pages/BatchTraceability";
import EtiquetaTimeline from "./pages/EtiquetaTimeline";
import EtiquetaAuditoria from "./pages/EtiquetaAuditoria";
import ContainersAbertos from "./features/logistica/ui/ContainersAbertos.page";
import EventosAuditoria from "./features/logistica/ui/EventosAuditoria.page";
import Requisicao from "./features/requisicoes/ui/Requisicao.page";
import ConclusaoRequisicao from "./features/requisicoes/ui/ConclusaoRequisicao.page";
import RequisicaoChegada from "./pages/RequisicaoChegada";
import RecebimentoBip from "./pages/RecebimentoBip";
import ProducaoDiaria from "./pages/ProducaoDiaria";
import Financeiro from "./pages/Financeiro";


import Movimentacoes from "./features/estoque/ui/Movimentacoes.page";
import Encomendas from "./features/encomendas/ui/Encomendas.page";
import { ProntaEntregaPage } from "./features/pronta-entrega";
import Eventos from "./features/eventos/ui/Eventos.page";
import EventDashboard from "./features/eventos/ui/EventDashboard";
import PJDashboard from "./features/eventos/ui/PJDashboard";
import Logistica from "./features/logistica/ui/Logistica.page";
import SeparacaoBipPage from "./features/logistica/ui/SeparacaoBipPage";
import NotasFiscais from "./features/notas-fiscais/ui/NotasFiscais.page";


import Usuarios from "./features/usuarios/ui/Usuarios.page";
import Funcionarios from "./features/funcionarios/ui/Funcionarios.page";
import Cargos from "./features/funcionarios/ui/Cargos.page";
import NovoFuncionario from "./features/funcionarios/ui/NovoFuncionario.page";
import FuncionarioPerfil from "./features/funcionarios/ui/FuncionarioPerfil.page";
import Experiencia from "./features/funcionarios/ui/Experiencia.page";
import Organograma from "./features/funcionarios/ui/Organograma.page";
import Desligamentos from "./features/funcionarios/ui/Desligamentos.page";
import Ferias from "./features/funcionarios/ui/Ferias.page";
import FeriasCalendario from "./features/funcionarios/ui/FeriasCalendario.page";
import MetodosPunitivos from "./features/funcionarios/ui/MetodosPunitivos.page";
import FuncionariosAnalytics from "./features/funcionarios/ui/Analytics.page";
import EsocialPage from "./features/funcionarios/ui/Esocial.page";
import PesquisaClimaPage from "./features/funcionarios/ui/PesquisaClima.page";
import ResponderPesquisaClimaPage from "./features/funcionarios/ui/ResponderPesquisaClima.page";
import MinhaContaPage from "./features/funcionarios/ui/MinhaConta.page";
import FreelancersPage from "./features/funcionarios/ui/Freelancers.page";
import Fluxogramas from "./pages/Fluxogramas";
import PaginaPicking from "./features/requisicoes/ui/PaginaPicking.page";
import LogisticsControlTower from "./features/logistica/ui/LogisticsControlTower.page";


import Scanner from "./pages/Scanner";


import Auth from "./pages/Auth";
import TestAuth from "./pages/TestAuth";
import TestAuthLogs from "./pages/TestAuthLogs";
import TestAuthDiagnostic from "./pages/TestAuthDiagnostic";
import NotFound from "./pages/NotFound";
import Configuracoes from "./pages/Configuracoes";
import ResetPassword from "./pages/ResetPassword";
import VerificacaoPerdas from "./pages/VerificacaoPerdas";
import Marketing from "./pages/Marketing";
import GerenciarProdutosMaster from "./pages/GerenciarProdutosMaster";
import FichasTecnicas from "./pages/producao/FichasTecnicas";
import RecipeConfigurator from "./pages/producao/RecipeConfigurator";
import CmvPage from "./features/financeiro/ui/Cmv.page";
import CmvConfiguratorPage from "./features/financeiro/ui/CmvConfigurator.page";
import Insumos from "./pages/producao/Insumos";
import AdminDashboard from "./features/admin/ui/AdminDashboard.page";
import { MiaInlineChat } from "./features/mia/ui/MiaInlineChat";
import { MiaOutcomesDashboard } from "./features/mia/ui/MiaOutcomesDashboard";
import MiaHealthDashboard from "./features/mia/ui/MiaHealthDashboard";
import MiaObservabilityDashboard from "./features/mia/ui/MiaObservabilityDashboard";
import MiaPatternsDashboard from "./features/mia/ui/MiaPatternsDashboard";
import MiaImproveDashboard from "./features/mia/ui/MiaImproveDashboard";
import { MiaProvider } from "@/shared/contexts/MiaContext";
import { MiaTelemetryRoot } from "@/features/mia/ui/MiaTelemetryRoot";
import AtendimentoVirtual from "./pages/AtendimentoVirtual";
import TvDashboardPage from "./features/tv-dashboard/ui/TvDashboard.page";
import TvMetasPage from "./features/tv-dashboard/ui/TvMetas.page";
import TvStoreDetailPage from "./features/tv-dashboard/ui/TvStoreDetail.page";

const queryClient = new QueryClient();

import { VersionUpdater } from "@/shared/ui/VersionUpdater";
import { GestaoSetorPage } from "@/features/gestao";

const App = () => {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider
        attribute="class"
        defaultTheme="light"
        enableSystem
        disableTransitionOnChange
      >
        <TooltipProvider>
          <VersionUpdater />
          <Toaster />
          <Sonner />
          <BrowserRouter
            future={{
              v7_startTransition: true,
              v7_relativeSplatPath: true,
            }}
          >
            <AuthProvider>
              <PermissionsProvider>
                <StoreProvider>
                  {/* MiaProvider ENVOLVE Routes — persiste state entre navegações.
                      Antes estava dentro de cada DashboardLayout → re-montava
                      em cada route change, fazendo chat sumir + tab resetar. */}
                  <MiaProvider>
                  <MiaTelemetryRoot />
                  <Routes>
                    <Route path="/" element={<RootRedirect />} />
                    <Route path="/perfil" element={<RootRedirect />} />
                    <Route path="/home" element={<Index />} />
                    <Route path="/auth" element={<Auth />} />
                    <Route path="/reset-password" element={<ResetPassword />} />
                    <Route path="/test-auth" element={<TestAuth />} />
                    <Route path="/test-auth-logs" element={<TestAuthLogs />} />
                    <Route path="/test-auth-diagnostic" element={<TestAuthDiagnostic />} />
                    <Route
                      path="/dashboard"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Dashboard />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    {/** Rotas de painéis removidas */}
                    <Route
                      path="/producao-diaria"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <ProducaoDiaria />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/etiquetas"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <LabelPrinting />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/lotes/rastreabilidade"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <BatchTraceability />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/etiquetas/auditoria"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <EtiquetaAuditoria />
