export function usePermissions() {
  const context = useContext(PermissionsContext);
  if (context === undefined) {
    throw new Error('usePermissions deve ser usado dentro de um PermissionsProvider');
  }
  return context;
}

// Hook para verificar permissões específicas
export function useRequirePermission(permissionName: string) {
  const { hasPermission, loading } = usePermissions();

  return {
    hasAccess: hasPermission(permissionName),
    loading
  };
}

// Hook para verificar acesso a módulos
export function useRequireModule(module: string) {
  const { canAccessModule, loading } = usePermissions();

  return {
    hasAccess: canAccessModule(module),
    loading
  };
}

import { usePermissions } from '@/shared/hooks/usePermissions';
import { Alert, AlertDescription } from '@/shared/ui/alert';
import { ShieldX } from 'lucide-react';

interface PermissionProtectedRouteProps {
  children: React.ReactNode;
  requiredPermission?: string;
  requiredModule?: string;
  requiredPermissions?: string[]; // Para múltiplas permissões (OR)
  requireAllPermissions?: string[]; // Para múltiplas permissões (AND)
  adminOnly?: boolean;
}

/**
 * Protege rotas verificando permissões do usuário autenticado.
 * Exibe mensagem de "Acesso Negado" com o role atual quando a verificação falha.
 *
 * @param children - Conteúdo da rota protegida.
 * @param requiredPermission - Permissão única necessária.
 * @param requiredModule - Módulo necessário para acesso.
 * @param requiredPermissions - Lista de permissões (basta uma -- lógica OR).
 * @param requireAllPermissions - Lista de permissões (todas necessárias -- lógica AND).
 * @param adminOnly - Se `true`, restringe acesso apenas a administradores.
 */
export function PermissionProtectedRoute({
  children,
  requiredPermission,
  requiredModule,
  requiredPermissions,
  requireAllPermissions,
  adminOnly = false,
}: PermissionProtectedRouteProps) {
  const {
    hasPermission,
    hasAnyPermission,
    canAccessModule,
    isAdmin,
    loading,
    userRole,
  } = usePermissions();

  // Admin bypass — admins always have full access
  if (!loading && isAdmin()) {
    return <>{children}</>;
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="flex flex-col items-center space-y-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          <p className="text-muted-foreground">Verificando permissões...</p>
        </div>
      </div>
    );
  }

  // Verificar se é admin only
  if (adminOnly && !isAdmin()) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="max-w-md w-full">
          <Alert className="border-destructive">
            <ShieldX className="h-4 w-4" />
            <AlertDescription className="mt-2">
              <div className="space-y-2">
                <p className="font-semibold">Acesso Negado</p>
                <p>
                  Esta funcionalidade é restrita apenas para administradores do
                  sistema.
                </p>
                <p className="text-sm text-muted-foreground">
                  Seu perfil atual:{' '}
                  <span className="font-medium">
                    {userRole?.role_display_name}
                  </span>
                </p>
              </div>
            </AlertDescription>
          </Alert>
        </div>
      </div>
    );
  }

  // Verificar permissão específica
  if (requiredPermission && !hasPermission(requiredPermission)) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="max-w-md w-full">
          <Alert className="border-destructive">
            <ShieldX className="h-4 w-4" />
            <AlertDescription className="mt-2">
              <div className="space-y-2">
                <p className="font-semibold">Acesso Negado</p>
                <p>
                  Você não possui permissão para acessar esta funcionalidade.
                </p>
                <p className="text-sm text-muted-foreground">
                  Seu perfil atual:{' '}
                  <span className="font-medium">
                    {userRole?.role_display_name}
                  </span>
                </p>
              </div>
            </AlertDescription>
          </Alert>
        </div>
      </div>
    );
  }

  // Verificar módulo
  if (requiredModule && !canAccessModule(requiredModule)) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="max-w-md w-full">
          <Alert className="border-destructive">
            <ShieldX className="h-4 w-4" />
            <AlertDescription className="mt-2">
              <div className="space-y-2">
                <p className="font-semibold">Acesso Negado</p>
                <p>
                  Você não possui acesso ao módulo{' '}
                  <span className="font-medium">{requiredModule}</span>.
                </p>
                <p className="text-sm text-muted-foreground">
                  Seu perfil atual:{' '}
                  <span className="font-medium">
                    {userRole?.role_display_name}
                  </span>
                </p>
              </div>
            </AlertDescription>
          </Alert>
        </div>
      </div>
    );
  }

  // Verificar múltiplas permissões (OR)
  if (requiredPermissions && !hasAnyPermission(requiredPermissions)) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="max-w-md w-full">
          <Alert className="border-destructive">
            <ShieldX className="h-4 w-4" />
            <AlertDescription className="mt-2">
              <div className="space-y-2">
                <p className="font-semibold">Acesso Negado</p>
                <p>
                  Você não possui nenhuma das permissões necessárias para
                  acessar esta funcionalidade.
                </p>
                <p className="text-sm text-muted-foreground">
                  Seu perfil atual:{' '}
                  <span className="font-medium">
                    {userRole?.role_display_name}
                  </span>
                </p>
              </div>
            </AlertDescription>
          </Alert>
        </div>
      </div>
    );
  }

  // Verificar múltiplas permissões (AND)
  if (
    requireAllPermissions &&
    !requireAllPermissions.every((perm) => hasPermission(perm))
  ) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="max-w-md w-full">
          <Alert className="border-destructive">
            <ShieldX className="h-4 w-4" />
            <AlertDescription className="mt-2">
              <div className="space-y-2">
                <p className="font-semibold">Acesso Negado</p>
                <p>
                  Você não possui todas as permissões necessárias para acessar
                  esta funcionalidade.
                </p>
                <p className="text-sm text-muted-foreground">
                  Seu perfil atual:{' '}
                  <span className="font-medium">
                    {userRole?.role_display_name}
                  </span>
                </p>
              </div>
            </AlertDescription>
          </Alert>
        </div>
      </div>
    );
  }

  return <>{children}</>;
}

