import React, { createContext, useContext, useState, useEffect, ReactNode, useRef } from 'react';
import { useAuth } from '@/shared/hooks/useAuth';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { supabase } from '@/integrations/supabase/client';
import { wideInfo, wideDebug, wideWarn, wideError } from '@/shared/lib/telemetry/wide-events';
import { recordStoreChange, recordStoreChangeDuration } from '@/shared/lib/telemetry/metrics';
import { recordRumStoreChange } from '@/shared/lib/telemetry/rum';
import { handleError } from '@/shared/lib/error-handler';

interface Store {
  id: number;
  name: string;
  address: string;
  shortName: string;
  tipo?: string; // 'Loja' | 'Fabrica' (do banco) - opcional para fallback
}

interface StoreContextType {
  selectedStore: Store | null;
  setSelectedStore: (store: Store) => void;
  // Forçar seleção programática (ignora permissões) - útil para páginas exclusivas da Fábrica
  forceSetSelectedStore: (predicate: (s: Store) => boolean) => void;
  stores: Store[];
  loading: boolean;
  canChangeStore: boolean;
}

// Lista predefinida de lojas (fallback caso não consiga carregar do banco)
// IDs atualizados conforme migration 20260303120000_reorganize_store_ids_add_brasilia_shopping
const STORES: Store[] = [
  { id: 1, name: 'Fábrica', address: 'Brasília - DF', shortName: 'Fábrica', tipo: 'Fabrica' },
  { id: 2, name: 'Momma Asa Sul', address: 'Brasília - DF', shortName: 'Asa Sul', tipo: 'Loja' },
  { id: 3, name: 'Momma Asa Norte', address: 'Asa Norte, Brasília - DF', shortName: 'Asa Norte', tipo: 'Loja' },
  { id: 4, name: 'Momma Lago Sul', address: 'Brasília - DF, Lago Sul', shortName: 'Lago Sul', tipo: 'Loja' },
  { id: 5, name: 'Momma Águas Claras', address: 'Águas Claras, Brasília - DF', shortName: 'Águas Claras', tipo: 'Loja' },
  { id: 6, name: 'Momma Brasília Shopping', address: 'Brasília Shopping, Brasília - DF', shortName: 'Brasília Shopping', tipo: 'Loja' }
];

// NOTA: Todos os dados existentes (produtos, movimentações, etc.)
// pertencem à loja Asa Sul. As lojas Lago Sul e Asa Norte
// ainda não possuem dados ou movimentações.

const StoreContext = createContext<StoreContextType | undefined>(undefined);

interface StoreProviderProps {
  children: ReactNode;
}

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { user, userProfile } = useAuth();
  const { isAdmin, canSwitchStore } = usePermissions();
  const [selectedStore, setSelectedStoreState] = useState<Store | null>(null);
  const [loading, setLoading] = useState(true);
  const [canChangeStore, setCanChangeStore] = useState(false);
  const [availableStores, setAvailableStores] = useState<Store[]>(STORES);

  // Carregar lojas do banco de dados
  const loadStoresFromDB = async () => {
    wideDebug('store.load_stores_start', 'Iniciando carregamento de lojas do banco', {
      attributes: { 'store.source': 'supabase' },
    });
    try {
      const { data, error } = await supabase
        .from('lojas')
        .select('id, nome, endereco, tipo')
        .eq('ativo', true)
        .order('nome');

      if (error) {
        wideError('store.load_stores_error', 'Erro ao carregar lojas do Supabase', {
          attributes: {
            'store.error_code': error.code,
            'store.error_message': error.message,
          },
        });
        throw error;
      }

      const storeCount = data?.length || 0;
      const formattedStores = data?.map(store => {
        // Gerar shortName baseado no nome da loja
        let shortName = store.nome;
        if (store.nome.startsWith('Momma ')) {
          shortName = store.nome.replace('Momma ', '');
        }
        if (store.nome.toLowerCase().includes('fábrica') || store.tipo === 'Fabrica') {
          shortName = 'Fábrica';
        }

        return {
          id: store.id,
          name: store.nome,
          address: store.endereco,
          shortName: shortName,
          tipo: store.tipo
        };
      }) || STORES;

      wideDebug('store.load_stores_success', `Lojas carregadas: ${storeCount}`, {
        attributes: {
          'store.count': storeCount,
          'store.source': 'supabase',
        },
      });
      setAvailableStores(formattedStores);
      return formattedStores;
    } catch (error) {
      handleError(error, { domain: 'store', operation: 'loadStoresFromDB', showToast: false });
      wideDebug('store.load_stores_fallback', 'Usando lojas predefinidas como fallback', {
        attributes: { 'store.fallback_count': STORES.length },
      });
      return STORES; // Fallback para lojas predefinidas
    }
  };

  // Carregar loja selecionada do localStorage ou perfil do usuário
  const loadSelectedStore = (stores: Store[]): Store | null => {
    wideDebug('store.select_start', 'Iniciando seleção de loja', {
      attributes: {
        'store.has_user_profile': !!userProfile,
        'store.can_change_store': userProfile?.can_change_store ?? false,
        'store.default_store_id': userProfile?.default_store_id ?? 0,
        'store.available_count': stores.length,
        'store.is_admin': isAdmin(),
      },
    });

    // Para usuários que NÃO podem alterar loja (não-admin), sempre usar default_store_id
    if (!canSwitchStore() && !userProfile?.can_change_store) {
      if (userProfile?.default_store_id) {
        const userStore = stores.find(s => s.id === userProfile.default_store_id);
        if (userStore) {
          localStorage.setItem('selectedStore', JSON.stringify(userStore));
          return userStore;
        }
      }
      // Fallback: Tentar recuperar do localStorage se o perfil ainda não carregou (estado transiente)
      // Isso evita que o usuário "caia" na Fábrica enquanto o perfil carrega
      if (!userProfile) {
        try {
          const saved = localStorage.getItem('selectedStore');
          if (saved) {
            const parsed = JSON.parse(saved);
            const store = stores.find(s => s.id === parsed.id);
            if (store) {
              wideDebug('store.select_cache', 'Sem perfil: usando cache local temporário', {
                attributes: { 'store.name': store.name, 'store.id': store.id },
              });
              return store;
            }
          }
        } catch (e) {
          handleError(e, { domain: 'store', operation: 'loadSelectedStore.localStorageFallback', showToast: false });
        }
      }

      // Fallback imediato: selecionar Fábrica quando perfil ainda não carregou ou loja padrão inválida
      const fabrica = stores.find(s => s.shortName === 'Fábrica' || s.name.toLowerCase().includes('fábrica'));
      if (fabrica) {
        localStorage.setItem('selectedStore', JSON.stringify(fabrica));
        return fabrica;
      }
      return null;
    }

    // Para admins/operações gerais ou usuários com permissão de alterar loja: usar localStorage primeiro
    if (canSwitchStore() || userProfile?.can_change_store) {
      // PRIORIDADE 1: Tentar carregar do localStorage primeiro (preservar contexto)
      try {
        const saved = localStorage.getItem('selectedStore');
        if (saved) {
          const parsed = JSON.parse(saved);
          const store = stores.find(s => s.id === parsed.id);
          if (store) {
            wideDebug('store.select_localStorage', 'Loja preservada do localStorage', {
              attributes: { 'store.name': store.name, 'store.id': store.id },
            });
            return store;
          } else {
            wideWarn('store.select_localStorage_invalid', 'Loja do localStorage não encontrada nas lojas disponíveis', {
              attributes: { 'store.invalid_id': parsed.id },
            });
            // Limpar localStorage inválido
            localStorage.removeItem('selectedStore');
          }
        }
      } catch (error) {
        handleError(error, { domain: 'store', operation: 'loadSelectedStore.localStorage', showToast: false });
        // Limpar localStorage corrompido
        localStorage.removeItem('selectedStore');
      }

      // PRIORIDADE 2: Se não há localStorage válido, usar loja padrão do perfil
      if (userProfile?.default_store_id) {
        const userStore = stores.find(s => s.id === userProfile.default_store_id);
        if (userStore) {
          wideDebug('store.select_profile_default', 'Usando loja padrão do perfil', {
            attributes: { 'store.name': userStore.name, 'store.id': userStore.id },
          });
          // Salvar no localStorage para preservar na próxima vez

