25	/** Contrato público do contexto de autenticação. */
26	interface AuthContextType {
27	  /** Usuário Supabase Auth (null se não autenticado). */
28	  user: User | null;
29	  /** Sessão ativa (contém access/refresh tokens). */
30	  session: Session | null;
31	  /** Perfil da tabela `profiles` (null durante carregamento). */
32	  userProfile: UserProfile | null;
33	  /** `true` enquanto sessão e perfil estão sendo carregados. */
34	  loading: boolean;
35	  /** `true` se o usuário existe mas ainda não foi aprovado por um admin. */
36	  needsApproval: boolean;
37	  /** Faz login com email/senha via Supabase Auth. */
38	  signIn: (
39	    email: string,
40	    password: string,
41	  ) => Promise<{ data: any; error: any }>;
42	  /** Faz logout e limpa sessão local. */
43	  signOut: () => Promise<void>;
44	  /** Recarrega o perfil do banco (útil após mudança de role). */
45	  refreshProfile: () => Promise<void>;
46	}
