import { createContext, useContext, useCallback, useEffect, useRef, useState, ReactNode } from 'react';
import { User, Session } from '@supabase/supabase-js';
import { supabase, SESSION_UNAUTHORIZED_EVENT } from '@/integrations/supabase/client';
import { recordUserLogin, recordUserLogout, recordError, recordDuration } from '@/shared/lib/telemetry/metrics';
import { withTrace } from '@/shared/lib/telemetry/tracer';
import { wideInfo, wideError, wideDebug } from '@/shared/lib/telemetry/wide-events';
import { rumSessionStart, rumSessionEnd } from '@/shared/lib/telemetry/rum';

/** Perfil do usuário carregado da tabela `profiles`. */
interface UserProfile {
  id: string;
  user_id: string;
  nome: string;
  username: string;
  ativo: boolean;
  role_id: number | null;
  approved: boolean;
  needs_approval: boolean;
  default_store_id: number | null;
  can_change_store: boolean;
  created_at: string;
  updated_at: string;
}

/** Contrato público do contexto de autenticação. */
interface AuthContextType {
  /** Usuário Supabase Auth (null se não autenticado). */
  user: User | null;
  /** Sessão ativa (contém access/refresh tokens). */
  session: Session | null;
  /** Perfil da tabela `profiles` (null durante carregamento). */
  userProfile: UserProfile | null;
  /** `true` enquanto sessão e perfil estão sendo carregados. */
  loading: boolean;
  /** `true` se o usuário existe mas ainda não foi aprovado por um admin. */
  needsApproval: boolean;
  /** Faz login com email/senha via Supabase Auth. */
  signIn: (
    email: string,
    password: string,
  ) => Promise<{ data: any; error: any }>;
  /** Faz logout e limpa sessão local. */
  signOut: () => Promise<void>;
  /** Recarrega o perfil do banco (útil após mudança de role). */
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Provedor de autenticação. Deve envolver toda a árvore que precisa de `useAuth`.
 *
 * Inicializa a sessão Supabase, carrega o perfil do usuário, e escuta
 * mudanças de auth state (login, logout, token refresh).
 */
export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [needsApproval, setNeedsApproval] = useState(false);
  const signInInProgressRef = useRef(false);
  const reauthInFlightRef = useRef(false);

  /**
   * Reage a um 401 (JWT expirado): tenta renovar a sessão uma única vez;
   * se o refresh falhar (refresh token também morto), faz signOut local —
   * `onAuthStateChange('SIGNED_OUT')` zera o estado e o `ProtectedRoute`
   * redireciona pra `/auth`. Evita ficar preso em 401 em cascata.
   */
  const handlePossibleExpiry = useCallback(async () => {
    if (reauthInFlightRef.current || signInInProgressRef.current) return;
    reauthInFlightRef.current = true;
    try {
      const { data, error } = await supabase.auth.refreshSession();
      if (error || !data.session) {
        await supabase.auth.signOut({ scope: 'local' });
      } else {
        setSession(data.session);
        setUser(data.session.user);
      }
    } catch {
      try {
        await supabase.auth.signOut({ scope: 'local' });
      } catch {
        /* garante limpeza local mesmo se a chamada falhar */
      }
    } finally {
      reauthInFlightRef.current = false;
    }
  }, []);

  const fetchUserProfile = async (userId: string, retryCount = 0): Promise<UserProfile | null> => {
    wideDebug('auth.fetchProfile', 'Buscando perfil do usuário', {
      domain: 'auth',
      attributes: { 'operation.name': 'fetchUserProfile', 'user.id': userId },
    });

    const MAX_RETRIES = 2;

